import express, { type ErrorRequestHandler } from "express";
import { authMiddleware } from "./auth";
import { sendError } from "./errors";
import { health, status } from "./handlers/misc";
import { eventsHandler } from "./events";
import { requestLog } from "./log";
import { mooringsRouter } from "./routes/moorings";
import { webhooksRouter } from "./routes/webhooks";

export function createApp() {
  const app = express();
  app.disable("x-powered-by");
  app.use(requestLog);
  app.use(express.json({ limit: "1mb" }));
  app.get("/healthz", health);
  app.use("/webhooks", webhooksRouter);
  app.use(authMiddleware);
  app.use("/v1/moorings", mooringsRouter);
  app.get("/v1/status", status);
  app.get("/v1/events", eventsHandler);
  app.use((_req, res) => res.status(404).json({ error: "not found" }));
  const onError: ErrorRequestHandler = (err, _req, res, _next) => sendError(res, err);
  app.use(onError);
  return app;
}

