import { Router } from "express";
import { verifyPelicanSignature } from "../pelican-signature";
import { handlePelicanEvent, type PelicanEvent } from "../handlers/pelican";

export const webhooksRouter = Router();

webhooksRouter.post("/pelican", async (req, res, next) => {
  try {
    const body = JSON.stringify(req.body);
    if (!verifyPelicanSignature(body, req.header("X-Pelican-Signature") ?? "")) {
      res.status(401).json({ error: "invalid signature" });
      return;
    }
    await handlePelicanEvent(req.body as PelicanEvent);
    res.status(204).end();
  } catch (err) {
    next(err);
  }
});

