export async function authenticate(req: IncomingMessage, res: ServerResponse): Promise<User | undefined> {
  const header = req.headers.authorization;
  if (!header) return void sendJson(res, 401, { error: "unauthorized" });
  try {
    return await verifyToken(header);
  } catch (err) {
    sendJson(res, err instanceof TokenScopeError || err instanceof TokenExpiredError ? 403 : 401, { error: "forbidden" });
  }
}

