import express, { Router } from "express";
import { verifyPelicanSignature } from "../pelican-signature";
import { handlePelicanEvent, type PelicanEvent } from "../handlers/pelican";

export const webhooksRouter = Router();

// Pelican signs the exact bytes it sends. Verify the HMAC over the raw body: parsing with express.json() and
// re-serialising with JSON.stringify changes the bytes (spacing, 12.50 -> 12.5), and no signature would match.
webhooksRouter.post("/pelican", express.raw({ type: "application/json", limit: "1mb" }), async (req, res, next) => {
  try {
    const raw = req.body as Buffer;
    if (!Buffer.isBuffer(raw) || !verifyPelicanSignature(raw, req.header("X-Pelican-Signature") ?? "")) {
      res.status(401).json({ error: "invalid signature" });
      return;
    }
    await handlePelicanEvent(JSON.parse(raw.toString("utf8")) as PelicanEvent);
    res.status(204).end();
  } catch (err) {
    next(err);
  }
});

